IF NOT EXISTS (SELECT 1 FROM [PhysicalVolumes] WHERE [Code] = N'17-08-001-03' AND [VolumeTypeId] = (SELECT [Id] FROM [PhysicalVolumeTypes] WHERE [Name] = N'БЭР'))
BEGIN
    INSERT INTO [PhysicalVolumes] ([Code], [Name], [Description], [VolumeTypeId], [ParentId], [ClassifierId], [UnitId], [IsAssessment], [IsArchived], [Coefficient], [CreatedAt])
    VALUES (N'17-08-001-03', N'Агрегат пусковой массой до 200 кг', N'01. Транспортирование оборудования от приобъектного склада к стволу шахты.02. Распаковка ящиков с оборудованием.03. Спуск в шахту, подъем, доставка по горным выработкам монтажных механизмов и материалов.04. Установка, выверка и крепление конструкций на штырях с вмазкой лап в готовые гнезда с разметкой мест установки деталей крепления, пробивкой или сверлением отверстий или гнезд в основании.05. Проверка исправности трансформатора, аппарата или агрегата.06. Установка и крепление трансформатора, аппарата или агрегата.07. Разделка концов кабелей.08. Ввод кабелей в камеру ввода и крепление их в муфтах.09. Присоединение жил к клеммам.10. Маркировка.11. Проверка.', (SELECT [Id] FROM [PhysicalVolumeTypes] WHERE [Name] = N'БЭР'), (SELECT [Id] FROM [PhysicalVolumes] WHERE [Code] = N'17-08-001' AND [VolumeTypeId] = (SELECT [Id] FROM [PhysicalVolumeTypes] WHERE [Name] = N'БЭР')), (SELECT [Id] FROM [IicWorkDirections] WHERE [Code] = N'IIC-3-5'), (SELECT [Id] FROM [UnitsOfMeasurement] WHERE [Name] = N'шт.'), 1, 0, 1, SYSUTCDATETIME());
